using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace ApiMcpServer.Tools;

/// <summary>
/// MCP tools that wrap a REST API via HttpClient.
/// The SDK injects HttpClient via constructor — it does NOT appear in the tool schema.
/// Only parameters with [Description] are exposed to the LLM.
/// </summary>
[McpServerToolType]
public class ApiTools(HttpClient httpClient, ILogger<ApiTools> logger)
{
    private static readonly JsonSerializerOptions JsonOptions = new() { WriteIndented = true };

    [McpServerTool, Description("Get a resource by its ID from the API.")]
    public async Task<string> GetResource(
        [Description("The unique identifier of the resource to fetch")] string id,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching resource {Id}", id);
        var response = await httpClient.GetAsync($"/api/resources/{id}", cancellationToken);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }

    [McpServerTool, Description("List resources with optional filtering. Returns JSON array.")]
    public async Task<string> ListResources(
        [Description("Filter by category (optional)")] string? category = null,
        [Description("Maximum number of results to return (default 10)")] int limit = 10,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Listing resources: category={Category}, limit={Limit}", category, limit);
        var query = $"?limit={limit}";
        if (!string.IsNullOrEmpty(category))
            query += $"&category={Uri.EscapeDataString(category)}";

        var response = await httpClient.GetAsync($"/api/resources{query}", cancellationToken);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }

    [McpServerTool(Destructive = false, ReadOnly = false),
     Description("Create a new resource. Returns the created resource as JSON.")]
    public async Task<string> CreateResource(
        [Description("Name for the new resource")] string name,
        [Description("Category to assign")] string category,
        [Description("Detailed description of the resource")] string description,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Creating resource {Name} in {Category}", name, category);
        var payload = JsonSerializer.Serialize(
            new { name, category, description }, JsonOptions);

        var content = new StringContent(payload, System.Text.Encoding.UTF8, "application/json");
        var response = await httpClient.PostAsync("/api/resources", content, cancellationToken);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }
}

